      ($vt$account.add-the-email-address-the-booking-was-made-with$vt$, $vt$Add the email address the booking was made with$vt$, $vt$Geben Sie die E-Mail-Adresse an, mit der gebucht wurde$vt$, $vt$Indiquez l’adresse e-mail utilisée pour réserver$vt$, $vt$أدخل البريد الإلكتروني الذي تم الحجز به$vt$, false, false, null),
      ($vt$account.add-the-surname-on-the-booking$vt$, $vt$Add the surname on the booking$vt$, $vt$Geben Sie den Nachnamen auf der Buchung an$vt$, $vt$Indiquez le nom de famille figurant sur la réservation$vt$, $vt$أدخل اسم العائلة الوارد في الحجز$vt$, false, false, null),
      ($vt$account.after-your-ride$vt$, $vt$After your ride$vt$, $vt$Nach Ihrer Fahrt$vt$, $vt$Après votre trajet$vt$, $vt$بعد رحلتك$vt$, false, false, null),
