      ($vt$account.all-your-bookings$vt$, $vt$All your bookings$vt$, $vt$Alle Ihre Buchungen$vt$, $vt$Toutes vos réservations$vt$, $vt$كل حجوزاتك$vt$, false, false, null),
      ($vt$account.allBookingsCount$vt$, $vt${n, plural, one {That is your only booking.} other {That is all # bookings.}}$vt$, $vt${n, plural, one {Das ist die einzige Buchung.} other {Das sind alle # Buchungen.}}$vt$, $vt${n, plural, one {C'est la seule réservation.} other {Ce sont vos # réservations.}}$vt$, $vt${n, plural, zero {لا حجوزات لعرضها.} one {هذا هو الحجز الوحيد.} two {هذان هما الحجزان الوحيدان.} few {هذه هي الحجوزات الـ# كلها.} many {هذه هي الحجوزات الـ# كلها.} other {هذه هي الحجوزات الـ# كلها.}}$vt$, false, false, null),
      ($vt$account.already-travelled$vt$, $vt$Already travelled$vt$, $vt$Bereits gefahren$vt$, $vt$Déjà effectués$vt$, $vt$رحلات سابقة$vt$, false, false, null),
