      ($vt$cookies.remembers-your-language-and-your-last-pickup-add$vt$, $vt$Remembers your language and your last pickup address so you do not type them twice.$vt$, $vt$Merkt sich Ihre Sprache und Ihre letzte Abholadresse, damit Sie sie nicht zweimal eingeben.$vt$, $vt$Retiennent votre langue et votre dernière adresse de prise en charge pour éviter de les ressaisir.$vt$, $vt$تتذكّر لغتك وآخر عنوان استقبال حتى لا تكتبهما مرتين.$vt$, false, false, null),
      ($vt$cookies.save-choices$vt$, $vt$Save choices$vt$, $vt$Auswahl speichern$vt$, $vt$Enregistrer mes choix$vt$, $vt$حفظ الاختيارات$vt$, false, false, null),
      ($vt$cookies.session-cookie-purpose$vt$, $vt$Keeps you signed in.$vt$, $vt$Hält Sie angemeldet.$vt$, $vt$Vous maintient connecté.$vt$, $vt$يبقيك مسجّل الدخول.$vt$, false, false, null),
      ($vt$cookies.session-to$vt$, $vt$Session to$vt$, $vt$Sitzung bis$vt$, $vt$Session jusqu’à$vt$, $vt$الجلسة حتى$vt$, false, false, null),
      ($vt$cookies.strictly-necessary$vt$, $vt$Strictly necessary$vt$, $vt$Unbedingt erforderlich$vt$, $vt$Strictement nécessaires$vt$, $vt$ضرورية تمامًا$vt$, false, false, null),
      ($vt$cookies.strictly-necessary-cookies-always-on$vt$, $vt$Strictly necessary cookies, always on$vt$, $vt$Unbedingt erforderliche Cookies, immer aktiv$vt$, $vt$Cookies strictement nécessaires, toujours actifs$vt$, $vt$ملفات الارتباط الضرورية، مفعّلة دائمًا$vt$, false, false, null),
      ($vt$cookies.strictly-necessary-cookies-keep-the-booking-flow$vt$, $vt$Strictly necessary cookies keep the booking flow working. Analytics and marketing stay off until you turn them on. Read the$vt$, $vt$Unbedingt erforderliche Cookies halten den Buchungsablauf am Laufen. Analyse und Marketing bleiben aus, bis Sie sie einschalten. Lesen Sie die$vt$, $vt$Les cookies strictement nécessaires font fonctionner la réservation. Mesure d’audience et marketing restent désactivés jusqu’à votre accord. Consultez la$vt$, $vt$ملفات الارتباط الضرورية تُبقي مسار الحجز يعمل. أما التحليلات والتسويق فتبقى معطّلة حتى تفعّلها. اقرأ$vt$, false, false, null),
      ($vt$cookies.tells-us-which-step-of-a-booking-people-abandon$vt$, $vt$Tells us which step of a booking people abandon, and reports errors so we can fix them.$vt$, $vt$Zeigt uns, bei welchem Schritt eine Buchung abgebrochen wird, und meldet Fehler, damit wir sie beheben können.$vt$, $vt$Nous indiquent à quelle étape une réservation est abandonnée et remontent les erreurs pour que nous les corrigions.$vt$, $vt$تُعلمنا بالخطوة التي يتوقّف عندها الحجز وتُبلغ عن الأخطاء لنصلحها.$vt$, false, false, null),
      ($vt$cookies.withdrawal-new-row$vt$, $vt$A new choice writes a new record. We never change an old one.$vt$, $vt$Eine neue Wahl schreibt einen neuen Eintrag. Alte Einträge ändern wir nicht.$vt$, $vt$Un nouveau choix écrit une nouvelle ligne. Nous ne modifions jamais une ancienne.$vt$, $vt$الاختيار الجديد يكتب سجلاً جديداً. لا نعدّل سجلاً قديماً.$vt$, false, false, null),
      ($vt$cookies.you-choose-what-we-measure$vt$, $vt$You choose what we measure$vt$, $vt$Sie entscheiden, was wir messen$vt$, $vt$Vous choisissez ce que nous mesurons$vt$, $vt$أنت تختار ما نقيسه$vt$, false, false, null),
      ($vt$cookies.your-choice-is-stored-for-store-consent-months-m$vt$, $vt$Your choice is stored for {STORE_CONSENT_MONTHS} months and can be changed any time.$vt$, $vt$Ihre Auswahl wird {STORE_CONSENT_MONTHS} Monate gespeichert und kann jederzeit geändert werden.$vt$, $vt$Votre choix est conservé {STORE_CONSENT_MONTHS} mois et peut être modifié à tout moment.$vt$, $vt$يُحفظ اختيارك مدة {STORE_CONSENT_MONTHS} شهرًا ويمكن تغييره في أي وقت.$vt$, false, false, null),
      ($vt$errors.errorBody$vt$, $vt$This one is on us. Try again, or head back to the homepage.$vt$, $vt$Das liegt an uns. Versuchen Sie es erneut, oder gehen Sie zurück zur Startseite.$vt$, $vt$C'est de notre côté. Réessayez, ou retournez à la page d'accueil.$vt$, $vt$هذا خطأ من جانبنا. حاول مرة أخرى، أو عد إلى الصفحة الرئيسية.$vt$, false, false, null),
      ($vt$errors.errorHomeCta$vt$, $vt$Go to the homepage$vt$, $vt$Zur Startseite$vt$, $vt$Aller à la page d'accueil$vt$, $vt$الذهاب إلى الصفحة الرئيسية$vt$, false, false, null),
      ($vt$errors.errorRetryCta$vt$, $vt$Try again$vt$, $vt$Erneut versuchen$vt$, $vt$Réessayer$vt$, $vt$حاول مرة أخرى$vt$, false, false, null),
      ($vt$errors.errorTitle$vt$, $vt$Something went wrong.$vt$, $vt$Etwas ist schiefgelaufen.$vt$, $vt$Un problème est survenu.$vt$, $vt$حدث خطأ ما.$vt$, false, false, null),
      ($vt$errors.notFoundBody$vt$, $vt$The link may be old or mistyped. Head back to the homepage, or contact support if you think this is wrong.$vt$, $vt$Der Link ist vielleicht veraltet oder falsch eingegeben. Gehen Sie zurück zur Startseite, oder wenden Sie sich an den Support, wenn Sie das für einen Fehler halten.$vt$, $vt$Le lien est peut-être ancien ou mal saisi. Retournez à la page d'accueil, ou contactez le support si vous pensez qu'il s'agit d'une erreur.$vt$, $vt$قد يكون الرابط قديمًا أو غير صحيح. عد إلى الصفحة الرئيسية، أو تواصل مع الدعم إذا كنت تعتقد أن هذا خطأ.$vt$, false, false, null),
      ($vt$errors.notFoundContactCta$vt$, $vt$Contact support$vt$, $vt$Support kontaktieren$vt$, $vt$Contacter le support$vt$, $vt$التواصل مع الدعم$vt$, false, false, null),
      ($vt$errors.notFoundHomeCta$vt$, $vt$Go to the homepage$vt$, $vt$Zur Startseite$vt$, $vt$Aller à la page d'accueil$vt$, $vt$الذهاب إلى الصفحة الرئيسية$vt$, false, false, null),
      ($vt$errors.notFoundTitle$vt$, $vt$We can't find that page.$vt$, $vt$Diese Seite finden wir nicht.$vt$, $vt$Nous ne trouvons pas cette page.$vt$, $vt$لم نتمكن من العثور على هذه الصفحة.$vt$, false, false, null),
      ($vt$faq.answers$vt$, $vt$Answers$vt$, $vt$Antworten$vt$, $vt$Réponses$vt$, $vt$إجابات$vt$, false, false, null),
      ($vt$faq.before-pickup-ask-us-and-we-will-send-them-soone$vt$, $vt$6 hours before pickup. Ask us at least 24 hours ahead and we will send them sooner.$vt$, $vt$6 Stunden vor der Abholung. Bitten Sie uns mindestens 24 Stunden im Voraus, und wir senden sie früher.$vt$, $vt$6 heures avant la prise en charge. Demandez-le au moins 24 heures à l’avance et nous les envoyons plus tôt.$vt$, $vt$6 ساعات قبل موعد الاستقبال. واطلب منّا قبل 24 ساعة على الأقل وسنرسلها أبكر.$vt$, false, false, $vt$fixed policy duration written into this specific copy, not a live count$vt$),
      ($vt$faq.before-pickup-call-or-message-them-directly-on-t$vt$, $vt$before pickup. Call or message them directly on the day.$vt$, $vt$vor der Abholung. Am Tag selbst rufen Sie ihn direkt an oder schreiben ihm.$vt$, $vt$avant la prise en charge. Le jour même, appelez-le ou écrivez-lui directement.$vt$, $vt$قبل موعد الاستقبال. وفي اليوم نفسه اتصل به أو راسله مباشرة.$vt$, false, false, null),
      ($vt$faq.before-that-or-if-nobody-answers-call-our-number$vt$, $vt$Before that, or if nobody answers, call our number and quote your booking reference. Keep your mobile reachable on the day of travel — the driver calls it on arrival.$vt$, $vt$Vorher, oder wenn niemand abnimmt, rufen Sie unsere Nummer an und nennen Ihre Buchungsreferenz. Halten Sie Ihr Mobiltelefon am Reisetag erreichbar — der Fahrer ruft bei der Ankunft an.$vt$, $vt$Avant cela, ou si personne ne répond, appelez notre numéro en indiquant votre référence. Gardez votre mobile joignable le jour du voyage — le chauffeur l’appelle à son arrivée.$vt$, $vt$قبل ذلك، أو إن لم يردّ أحد، اتصل برقمنا واذكر رقم حجزك. وأبقِ جوالك متاحًا يوم السفر — فالسائق يتصل به عند وصوله.$vt$, false, false, null),
      ($vt$faq.can-i-bring-my-own-child-or-booster-seat$vt$, $vt$Can I bring my own child or booster seat?$vt$, $vt$Darf ich meinen eigenen Kindersitz mitbringen?$vt$, $vt$Puis-je apporter mon siège enfant ou rehausseur ?$vt$, $vt$هل يمكنني إحضار مقعد طفل خاص بي؟$vt$, false, false, null),
      ($vt$faq.can-i-cancel-or-change-my-booking$vt$, $vt$Can I cancel or change my booking?$vt$, $vt$Kann ich meine Buchung stornieren oder ändern?$vt$, $vt$Puis-je annuler ou modifier ma réservation ?$vt$, $vt$هل يمكنني إلغاء الحجز أو تعديله؟$vt$, false, false, null),
      ($vt$faq.cancel-early-and-you-get-the-most-back-the-close$vt$, $vt$Cancel early and you get the most back; the closer to pickup, the less, because a driver is already committed to your journey. Flight delays are handled separately and cost you nothing when we have your flight number.$vt$, $vt$Früh stornieren bringt am meisten zurück; je näher an der Abholung, desto weniger, weil bereits ein Fahrer für Ihre Fahrt gebunden ist. Flugverspätungen werden separat behandelt und kosten Sie nichts, wenn uns Ihre Flugnummer vorliegt.$vt$, $vt$Annulez tôt et vous récupérez le plus ; plus on approche de la prise en charge, moins il reste, car un chauffeur est déjà engagé sur votre trajet. Les retards de vol sont traités à part et ne vous coûtent rien si nous avons votre numéro de vol.$vt$, $vt$الإلغاء المبكر يعيد لك القدر الأكبر، وكلما اقترب موعد الاستقبال قلّ المبلغ لأن سائقًا صار مرتبطًا برحلتك. أما تأخّر الرحلات الجوية فيُعالَج على حدة ولا يكلّفك شيئًا متى كان رقم رحلتك لدينا.$vt$, false, false, null),
      ($vt$faq.cannot-reach-either-call-us-and-quote-your-booki$vt$, $vt$Cannot reach either? Call us and quote your booking reference and we will do it for you.$vt$, $vt$Kommen Sie an keines von beidem heran? Rufen Sie uns mit Ihrer Buchungsreferenz an, wir erledigen es für Sie.$vt$, $vt$Vous n’accédez ni à l’un ni à l’autre ? Appelez-nous en indiquant votre référence et nous le ferons pour vous.$vt$, $vt$تعذّر عليك الوصول إلى أيٍّ منهما؟ اتصل بنا واذكر رقم حجزك ونتولّى الأمر عنك.$vt$, false, false, null),
      ($vt$faq.card-payment-processed-by-stripe-every-method-av$vt$, $vt$Card payment, processed by Stripe. Every method available for your booking is shown at checkout before you pay.$vt$, $vt$Kartenzahlung, abgewickelt über Stripe. Alle für Ihre Buchung verfügbaren Zahlungsarten werden vor der Zahlung an der Kasse angezeigt.$vt$, $vt$Paiement par carte, traité par Stripe. Tous les moyens disponibles pour votre réservation s’affichent au paiement, avant le débit.$vt$, $vt$الدفع بالبطاقة عبر Stripe. وتظهر كل الوسائل المتاحة لحجزك عند الدفع قبل إتمامه.$vt$, false, false, null),
      ($vt$faq.categories$vt$, $vt$Categories$vt$, $vt$Kategorien$vt$, $vt$Catégories$vt$, $vt$الفئات$vt$, false, false, null),
      ($vt$faq.collapse-all$vt$, $vt$Collapse all$vt$, $vt$Alle schliessen$vt$, $vt$Tout replier$vt$, $vt$اطوِ الكل$vt$, false, false, null),
      ($vt$faq.could-not-load-questions$vt$, $vt$Could not load questions$vt$, $vt$Fragen konnten nicht geladen werden$vt$, $vt$Impossible de charger les questions$vt$, $vt$تعذّر تحميل الأسئلة$vt$, false, false, null),
      ($vt$faq.do-i-need-an-account-to-book$vt$, $vt$Do I need an account to book?$vt$, $vt$Brauche ich für die Buchung ein Konto?$vt$, $vt$Faut-il un compte pour réserver ?$vt$, $vt$هل أحتاج حسابًا للحجز؟$vt$, false, false, null),
      ($vt$faq.do-i-need-to-tip-the-chauffeur$vt$, $vt$Do I need to tip the chauffeur?$vt$, $vt$Muss ich dem Chauffeur Trinkgeld geben?$vt$, $vt$Dois-je donner un pourboire au chauffeur ?$vt$, $vt$هل عليّ إعطاء السائق إكرامية؟$vt$, false, false, null),
      ($vt$faq.every-transfer-is-booked-ahead-and-assigned-to-a$vt$, $vt$Every transfer is booked ahead and assigned to a named driver. You are not waiting for a car to be found — at the agreed time it is already there.$vt$, $vt$Jeder Transfer wird im Voraus gebucht und einem namentlichen Fahrer zugeteilt. Sie warten nicht darauf, dass ein Auto gefunden wird — zur vereinbarten Zeit steht es bereits da.$vt$, $vt$Chaque transfert est réservé à l’avance et confié à un chauffeur nommé. Vous n’attendez pas qu’une voiture soit trouvée — à l’heure convenue elle est déjà là.$vt$, $vt$كل رحلة تُحجز مسبقًا وتُسند إلى سائق بالاسم. لست في انتظار إيجاد سيارة — ففي الموعد المتفق عليه تكون موجودة.$vt$, false, false, null),
      ($vt$faq.expand-all$vt$, $vt$Expand all$vt$, $vt$Alle öffnen$vt$, $vt$Tout déplier$vt$, $vt$وسّع الكل$vt$, false, false, null),
      ($vt$faq.frequently-asked-questions$vt$, $vt$Frequently asked questions$vt$, $vt$Häufig gestellte Fragen$vt$, $vt$Questions fréquentes$vt$, $vt$الأسئلة الشائعة$vt$, false, false, null),
      ($vt$faq.from-the-manage-booking-link-in-your-confirmatio$vt$, $vt$From the manage-booking link in your confirmation email, or from your account if you made one. You get a cancellation confirmation in writing; keep it, because that is what the refund is calculated from.$vt$, $vt$Über den Link zur Buchungsverwaltung in Ihrer Bestätigungs-E-Mail oder in Ihrem Konto, falls Sie eines angelegt haben. Sie erhalten eine schriftliche Stornobestätigung — bewahren Sie sie auf, denn danach wird die Rückerstattung berechnet.$vt$, $vt$Depuis le lien de gestion dans votre e-mail de confirmation, ou depuis votre compte si vous en avez un. Vous recevez une confirmation d’annulation par écrit ; conservez-la, c’est sur elle qu’est calculé le remboursement.$vt$, $vt$من رابط إدارة الحجز في رسالة التأكيد، أو من حسابك إن أنشأت واحدًا. وستصلك تأكيد إلغاء مكتوب؛ احتفظ به لأن الاسترداد يُحتسب على أساسه.$vt$, false, false, null),
      ($vt$faq.how-can-i-change-the-date-or-time-of-my-booking$vt$, $vt$How can I change the date or time of my booking?$vt$, $vt$Wie ändere ich Datum oder Uhrzeit meiner Buchung?$vt$, $vt$Comment modifier la date ou l’heure de ma réservation ?$vt$, $vt$كيف أغيّر تاريخ حجزي أو وقته؟$vt$, false, false, null),
      ($vt$faq.how-do-i-cancel-my-ride$vt$, $vt$How do I cancel my ride?$vt$, $vt$Wie storniere ich meine Fahrt?$vt$, $vt$Comment annuler mon trajet ?$vt$, $vt$كيف ألغي رحلتي؟$vt$, false, false, null),
      ($vt$faq.how-do-i-get-in-touch-with-my-chauffeur$vt$, $vt$How do I get in touch with my chauffeur?$vt$, $vt$Wie erreiche ich meinen Chauffeur?$vt$, $vt$Comment joindre mon chauffeur ?$vt$, $vt$كيف أتواصل مع سائقي؟$vt$, false, false, null),
      ($vt$faq.how-far-in-advance-do-i-need-to-book$vt$, $vt$How far in advance do I need to book?$vt$, $vt$Wie lange im Voraus muss ich buchen?$vt$, $vt$Combien de temps à l’avance faut-il réserver ?$vt$, $vt$كم من الوقت يلزم للحجز مسبقًا؟$vt$, false, false, null),
      ($vt$faq.if-the-new-time-changes-the-fare-you-pay-or-we-r$vt$, $vt$If the new time changes the fare, you pay or we refund the difference, and never more than the difference.$vt$, $vt$Ändert die neue Zeit den Preis, zahlen Sie die Differenz oder wir erstatten sie — nie mehr als die Differenz.$vt$, $vt$Si la nouvelle heure modifie le tarif, vous payez ou nous remboursons la différence, et jamais plus que la différence.$vt$, $vt$إن غيّر الموعد الجديد السعر، تدفع الفرق أو نردّه لك — ولا شيء أكثر من الفرق.$vt$, false, false, null),
      ($vt$faq.if-your-question-is-about-a-booking-you-have-alr$vt$, $vt$If your question is about a booking you have already made, open it directly — that is faster than writing to us.$vt$, $vt$Betrifft Ihre Frage eine bereits getätigte Buchung, öffnen Sie diese direkt — das geht schneller, als uns zu schreiben.$vt$, $vt$Si votre question porte sur une réservation déjà faite, ouvrez-la directement — c’est plus rapide que de nous écrire.$vt$, $vt$إن كان سؤالك عن حجز قائم، افتحه مباشرة — فذلك أسرع من مراسلتنا.$vt$, false, false, null),
      ($vt$faq.immediately-after-payment-by-email-it-carries-yo$vt$, $vt$Immediately after payment, by email. It carries your booking reference, the pickup time and address, the vehicle class and the price you paid.$vt$, $vt$Sofort nach der Zahlung per E-Mail. Sie enthält Ihre Buchungsreferenz, Abholzeit und -adresse, die Fahrzeugklasse und den bezahlten Preis.$vt$, $vt$Immédiatement après le paiement, par e-mail. Elle porte votre référence, l’heure et l’adresse de prise en charge, la classe du véhicule et le prix payé.$vt$, $vt$فور الدفع، عبر البريد الإلكتروني. وتحمل رقم حجزك ووقت الاستقبال وعنوانه وفئة المركبة والسعر المدفوع.$vt$, false, false, null),
      ($vt$faq.included-at-the-airport$vt$, $vt$Included at the airport$vt$, $vt$Am Flughafen inbegriffen$vt$, $vt$Inclus à l’aéroport$vt$, $vt$مشمول في المطار$vt$, false, false, null),
      ($vt$faq.is-the-price-i-see-the-final-price$vt$, $vt$Is the price I see the final price?$vt$, $vt$Ist der angezeigte Preis der Endpreis?$vt$, $vt$Le prix affiché est-il le prix final ?$vt$, $vt$هل السعر الظاهر هو السعر النهائي؟$vt$, false, false, null),
      ($vt$faq.luggage-and-seats-in-full$vt$, $vt$Luggage and seats in full$vt$, $vt$Gepäck und Sitze im Detail$vt$, $vt$Bagages et sièges en détail$vt$, $vt$الأمتعة والمقاعد بالتفصيل$vt$, false, false, null),
      ($vt$faq.meet-greet-airports$vt$, $vt$Meet greet airports$vt$, $vt$Meet greet airports$vt$, $vt$Meet greet airports$vt$, $vt$Meet greet airports$vt$, true, false, null),
      ($vt$faq.no-guest-checkout-takes-an-email-address-and-a-m$vt$, $vt$No. Guest checkout takes an email address and a mobile number — the address for your confirmation, the number for the driver to call on arrival. You can open an account later if you want your transfers in one place.$vt$, $vt$Nein. Für die Gastbuchung genügen E-Mail-Adresse und Mobilnummer — die Adresse für Ihre Bestätigung, die Nummer für den Anruf des Fahrers bei der Ankunft. Ein Konto können Sie später eröffnen, wenn Sie Ihre Transfers gebündelt sehen möchten.$vt$, $vt$Non. La commande en tant qu’invité demande une adresse e-mail et un numéro de mobile — l’adresse pour votre confirmation, le numéro pour l’appel du chauffeur à l’arrivée. Vous pourrez ouvrir un compte plus tard pour réunir vos transferts.$vt$, $vt$لا. يكفي في الحجز كضيف بريد إلكتروني ورقم جوال — البريد لتأكيد الحجز، والرقم ليتصل بك السائق عند الوصول. ويمكنك فتح حساب لاحقًا لتجميع رحلاتك في مكان واحد.$vt$, false, false, null),
      ($vt$faq.no-the-gratuity-is-already-in-the-price-you-were$vt$, $vt$No. The gratuity is already in the price you were shown, along with tolls and airport access fees. Nothing is expected on top and no driver will ask.$vt$, $vt$Nein. Das Trinkgeld ist im gezeigten Preis bereits enthalten, ebenso Maut und Flughafengebühren. Es wird nichts darüber hinaus erwartet, und kein Fahrer fragt danach.$vt$, $vt$Non. Le pourboire est déjà compris dans le prix affiché, tout comme les péages et les taxes d’accès à l’aéroport. Rien n’est attendu en plus et aucun chauffeur ne le demandera.$vt$, $vt$لا. الإكرامية مشمولة أصلًا في السعر المعروض، ومعها الرسوم ورسوم دخول المطار. ولا يُتوقّع شيء إضافي ولن يطلبه أي سائق.$vt$, false, false, null),
      ($vt$faq.open-your-booking-from-the-link-in-your-confirma$vt$, $vt$Open your booking from the link in your confirmation email, or from your account, and change it there. The change takes effect when we confirm it in writing — not when you send it.$vt$, $vt$Öffnen Sie Ihre Buchung über den Link in der Bestätigungs-E-Mail oder in Ihrem Konto und ändern Sie sie dort. Die Änderung gilt, sobald wir sie schriftlich bestätigen — nicht schon beim Absenden.$vt$, $vt$Ouvrez votre réservation depuis le lien de l’e-mail de confirmation, ou depuis votre compte, et modifiez-la là. La modification prend effet à notre confirmation écrite, pas à votre envoi.$vt$, $vt$افتح حجزك من الرابط في رسالة التأكيد أو من حسابك وعدّله هناك. ويسري التعديل حين نؤكّده كتابةً، لا حين ترسله.$vt$, false, false, null),
      ($vt$faq.pending-client-input$vt$, $vt$Pending client input$vt$, $vt$Kundenangabe ausstehend$vt$, $vt$En attente d’une réponse du client$vt$, $vt$بانتظار معلومات من العميل$vt$, false, false, null),
      ($vt$faq.placeholder-the-cancellation-and-change-policy-i$vt$, $vt$Placeholder — the cancellation and change policy is with the client and their legal advisers. No window, fee or refund term is stated here until it is agreed.$vt$, $vt$Platzhalter — die Stornierungs- und Änderungsbedingungen liegen beim Kunden und seiner Rechtsberatung. Bis zur Einigung steht hier keine Frist, Gebühr oder Rückerstattungsregel.$vt$, $vt$Espace réservé — la politique d’annulation et de modification est chez le client et ses conseils juridiques. Aucun délai, frais ni terme de remboursement n’est indiqué ici avant accord.$vt$, $vt$نص مؤقت — سياسة الإلغاء والتعديل لدى العميل ومستشاريه القانونيين. ولا تُذكر هنا مدة أو رسم أو شرط استرداد قبل الاتفاق.$vt$, false, false, null),
      ($vt$faq.placeholder-the-minimum-notice-before-a-pickup-h$vt$, $vt$Placeholder — the minimum notice before a pickup has not been set yet, so no cut-off is stated here. The rule goes into this answer once the client confirms it.$vt$, $vt$Platzhalter — die Mindestvorlaufzeit vor einer Abholung ist noch nicht festgelegt, deshalb steht hier keine Frist. Die Regel kommt in diese Antwort, sobald der Kunde sie bestätigt.$vt$, $vt$Espace réservé — le délai minimum avant une prise en charge n’est pas encore fixé, donc aucune limite n’est indiquée ici. La règle entrera dans cette réponse dès que le client la confirmera.$vt$, $vt$نص مؤقت — لم تُحدّد بعد أقل مدة إشعار قبل الاستقبال، لذا لا يُذكر هنا أي حدّ زمني. وستُدرج القاعدة في هذه الإجابة بعد تأكيد العميل.$vt$, false, false, null),
      ($vt$faq.questions-answered$vt$, $vt$Questions, answered$vt$, $vt$Fragen, beantwortet$vt$, $vt$Vos questions, nos réponses$vt$, $vt$أسئلة وإجابات$vt$, false, false, null),
      ($vt$faq.questionsCount$vt$, $vt${n, plural, one {# question} other {# questions}}$vt$, $vt${n, plural, one {# Frage} other {# Fragen}}$vt$, $vt${n, plural, one {# question} other {# questions}}$vt$, $vt${n, plural, zero {لا أسئلة} one {سؤال واحد} two {سؤالان} few {# أسئلة} many {# سؤالًا} other {# سؤال}}$vt$, false, false, null),
      ($vt$faq.see-all-questions$vt$, $vt$See all questions$vt$, $vt$Alle Fragen ansehen$vt$, $vt$Voir toutes les questions$vt$, $vt$عرض كل الأسئلة$vt$, false, false, null),
      ($vt$faq.single-source-of-truth$vt$, $vt$Single source of truth$vt$, $vt$Eine einzige verbindliche Quelle$vt$, $vt$Une seule source de vérité$vt$, $vt$مرجع واحد موثوق$vt$, false, false, null),
      ($vt$faq.still-not-answered$vt$, $vt$Still not answered?$vt$, $vt$Noch keine Antwort gefunden?$vt$, $vt$Toujours sans réponse ?$vt$, $vt$لم تجد إجابتك؟$vt$, false, false, null),
      ($vt$faq.swiss-law-decides-which-seat-a-child-needs-and-t$vt$, $vt$Swiss law decides which seat a child needs, and the driver will not set off without it. Tell us the children's ages at booking and we will get it right.$vt$, $vt$Das Schweizer Recht bestimmt, welchen Sitz ein Kind braucht, und der Fahrer fährt ohne ihn nicht los. Nennen Sie uns bei der Buchung das Alter der Kinder, dann stimmt es.$vt$, $vt$La loi suisse détermine le siège nécessaire à un enfant, et le chauffeur ne partira pas sans lui. Donnez-nous l’âge des enfants à la réservation et ce sera juste.$vt$, $vt$القانون السويسري يحدّد المقعد الذي يحتاجه الطفل، ولن ينطلق السائق بدونه. أخبرنا بأعمار الأطفال عند الحجز ليكون الاختيار صحيحًا.$vt$, false, false, null),
      ($vt$faq.the-deadline-lives-here$vt$, $vt$The deadline lives here$vt$, $vt$Die Frist steht hier$vt$, $vt$Le délai est indiqué ici$vt$, $vt$المهلة موضّحة هنا$vt$, false, false, null),
      ($vt$faq.the-things-travellers-ask-us-most-anything-with$vt$, $vt$The things travellers ask us most. Anything with a number or a deadline attached links to the page that owns it, so you are never reading two versions of the same rule.$vt$, $vt$Was Reisende uns am häufigsten fragen. Alles mit einer Zahl oder einer Frist verweist auf die Seite, die sie verantwortet — so lesen Sie nie zwei Fassungen derselben Regel.$vt$, $vt$Ce que les voyageurs nous demandent le plus. Tout ce qui comporte un chiffre ou un délai renvoie à la page qui en est responsable : vous ne lisez jamais deux versions d’une même règle.$vt$, $vt$أكثر ما يسألنا عنه المسافرون. وكل ما يحمل رقمًا أو مهلة يحيل إلى الصفحة المسؤولة عنه، فلا تقرأ نسختين من القاعدة نفسها.$vt$, false, false, null),
      ($vt$faq.three-questions$vt$, $vt$Three questions$vt$, $vt$Drei Fragen$vt$, $vt$Trois questions$vt$, $vt$ثلاثة أسئلة$vt$, false, false, null),
      ($vt$faq.two-questions$vt$, $vt$Two questions$vt$, $vt$Zwei Fragen$vt$, $vt$Deux questions$vt$, $vt$سؤالان$vt$, false, false, null),
      ($vt$faq.we-do-not-restate-the-windows-or-the-shares-here$vt$, $vt$We do not restate the windows or the shares here, on purpose. One page owns them, and it is kept correct.$vt$, $vt$Die Fristen und Anteile wiederholen wir hier bewusst nicht. Eine Seite verantwortet sie, und die wird korrekt gehalten.$vt$, $vt$Nous ne répétons pas ici les délais ni les parts, volontairement. Une seule page en est responsable, et elle est tenue à jour.$vt$, $vt$لا نكرّر هنا المهل أو النسب عن قصد. صفحة واحدة تملكها وتبقى صحيحة.$vt$, false, false, null),
      ($vt$faq.what-is-the-cancellation-policy$vt$, $vt$What is the cancellation policy?$vt$, $vt$Wie lauten die Stornierungsbedingungen?$vt$, $vt$Quelle est la politique d’annulation ?$vt$, $vt$ما سياسة الإلغاء؟$vt$, false, false, null),
      ($vt$faq.what-payment-methods-do-you-accept$vt$, $vt$What payment methods do you accept?$vt$, $vt$Welche Zahlungsarten akzeptieren Sie?$vt$, $vt$Quels moyens de paiement acceptez-vous ?$vt$, $vt$ما وسائل الدفع المقبولة؟$vt$, false, false, null),
      ($vt$faq.what-the-fare-includes$vt$, $vt$What the fare includes$vt$, $vt$Was im Preis enthalten ist$vt$, $vt$Ce que le tarif comprend$vt$, $vt$ما يشمله السعر$vt$, false, false, null),
      ($vt$faq.what-you-get-back-lives-here$vt$, $vt$What you get back lives here$vt$, $vt$Was Sie zurückerhalten, steht hier$vt$, $vt$Ce qui vous est remboursé est indiqué ici$vt$, $vt$ما تستردّه موضّح هنا$vt$, false, false, null),
      ($vt$faq.when-will-i-receive-my-booking-confirmation$vt$, $vt$When will I receive my booking confirmation?$vt$, $vt$Wann erhalte ich meine Buchungsbestätigung?$vt$, $vt$Quand vais-je recevoir ma confirmation ?$vt$, $vt$متى أستلم تأكيد الحجز؟$vt$, false, false, null),
      ($vt$faq.yes-and-it-travels-free-we-can-also-provide-one$vt$, $vt$Yes, and it travels free. We can also provide one — request it when you book so the right seat is in the right vehicle.$vt$, $vt$Ja, und er fährt kostenlos mit. Wir stellen auch einen — fordern Sie ihn bei der Buchung an, damit der richtige Sitz im richtigen Fahrzeug ist.$vt$, $vt$Oui, et il voyage gratuitement. Nous pouvons aussi en fournir un — demandez-le à la réservation pour que le bon siège soit dans le bon véhicule.$vt$, $vt$نعم، وينتقل مجانًا. ويمكننا توفير واحد أيضًا — اطلبه عند الحجز ليكون المقعد المناسب في المركبة المناسبة.$vt$, false, false, null),
      ($vt$faq.yes-your-fare-is-calculated-from-the-route-and-t$vt$, $vt$Yes. Your fare is calculated from the route and the vehicle class before you book, confirmed in writing, and it does not change afterwards. No meter, no surge, nothing added at the airport.$vt$, $vt$Ja. Ihr Preis wird vor der Buchung aus Route und Fahrzeugklasse berechnet, schriftlich bestätigt und ändert sich danach nicht mehr. Kein Taxameter, keine Zuschläge, nichts kommt am Flughafen dazu.$vt$, $vt$Oui. Votre tarif est calculé avant la réservation à partir du trajet et de la classe, confirmé par écrit, et il ne change plus ensuite. Pas de compteur, pas de majoration, rien d’ajouté à l’aéroport.$vt$, $vt$نعم. يُحتسب سعرك قبل الحجز من المسار وفئة المركبة، ويُؤكَّد كتابةً، ولا يتغيّر بعد ذلك. بلا عدّاد ولا زيادة ولا إضافات في المطار.$vt$, false, false, null),
      ($vt$faq.you-get-their-name-and-direct-number-by-sms-and$vt$, $vt$You get their name and direct number by SMS and email 6 hours$vt$, $vt$Namen und Direktnummer erhalten Sie per SMS und E-Mail 6 Stunden$vt$, $vt$Vous recevez son nom et son numéro direct par SMS et e-mail 6 heures$vt$, $vt$يصلك اسمه ورقمه المباشر عبر رسالة نصية والبريد 6 ساعات$vt$, false, false, $vt$fixed policy duration written into this specific copy, not a live count$vt$),
      ($vt$faq.your-driver-waits-in-the-arrivals-hall-with-a-na$vt$, $vt$Your driver waits in the arrivals hall with a name sign, helps with the bags and walks you to the car. We watch the flight, so a delay moves the pickup without you doing anything. Available at$vt$, $vt$Ihr Fahrer wartet mit Namensschild in der Ankunftshalle, hilft mit dem Gepäck und begleitet Sie zum Fahrzeug. Wir beobachten den Flug, sodass eine Verspätung die Abholung verschiebt, ohne dass Sie etwas tun. Verfügbar an$vt$, $vt$Votre chauffeur attend dans le hall des arrivées avec une pancarte, aide avec les bagages et vous accompagne à la voiture. Nous suivons le vol : un retard décale la prise en charge sans que vous fassiez quoi que ce soit. Disponible à$vt$, $vt$ينتظرك سائقك في صالة الوصول حاملًا لافتة باسمك، ويساعدك في الأمتعة ويرافقك إلى السيارة. ونحن نتابع الرحلة، فالتأخير يؤجّل الاستقبال دون أي إجراء منك. متاح في$vt$, false, false, null),
      ($vt$faq.your-drivers-name-vehicle-and-telephone-number-a$vt$, $vt$Your driver's name, vehicle and telephone number arrive separately, by SMS and email,$vt$, $vt$Name, Fahrzeug und Telefonnummer Ihres Fahrers kommen separat, per SMS und E-Mail,$vt$, $vt$Le nom, le véhicule et le numéro de votre chauffeur arrivent séparément, par SMS et e-mail,$vt$, $vt$يصلك اسم سائقك ومركبته ورقم هاتفه بشكل منفصل، عبر رسالة نصية والبريد،$vt$, false, false, null),
