      ($vt$home.type-a-flight-number-and-the-pickup-point-and-ti$vt$, $vt$Type a flight number and the pickup point and time come from the arrival. Nothing to look up yourself.$vt$, $vt$Flugnummer eingeben — Abholort und Zeit kommen direkt aus der Ankunft. Sie müssen nichts nachschlagen.$vt$, $vt$Saisissez un numéro de vol : le lieu et l’heure de prise en charge viennent de l’arrivée. Rien à chercher vous-même.$vt$, $vt$أدخل رقم الرحلة، ويُحدَّد مكان ووقت الاستقبال من موعد الوصول. لا شيء تبحث عنه بنفسك.$vt$, false, false, null),
      ($vt$home.vetted-for-airport-and-corporate-travel$vt$, $vt$Vetted for airport and corporate travel.$vt$, $vt$Geprüft für Flughafen- und Geschäftsfahrten.$vt$, $vt$Sélectionnés pour les trajets aéroport et affaires.$vt$, $vt$مختارون لرحلات المطار والأعمال.$vt$, false, false, null),
      ($vt$home.we-drive-from-dietikon-zh-zurich-and-geneva-airp$vt$, $vt$We drive from Dietikon ZH — Zurich and Geneva airports, the city, and the Alpine routes we run every week.$vt$, $vt$Wir fahren ab Dietikon ZH — Flughäfen Zürich und Genf, die Stadt und die Alpenrouten, die wir jede Woche bedienen.$vt$, $vt$Nous partons de Dietikon ZH — aéroports de Zurich et Genève, la ville, et les routes alpines que nous faisons chaque semaine.$vt$, $vt$ننطلق من ديتيكون بزيورخ — مطارا زيورخ وجنيف، والمدينة، والمسارات الألبية التي نسلكها كل أسبوع.$vt$, false, false, null),
      ($vt$home.why-vamos$vt$, $vt$Why Vamos$vt$, $vt$Warum Vamos$vt$, $vt$Pourquoi Vamos$vt$, $vt$لماذا فاموس$vt$, false, false, null),
      ($vt$home.your-driver-is-assigned-to-your-booking-and-waits$vt$, $vt$Your driver is assigned to your booking and waits at the curb with a name board.$vt$, $vt$Ihr Fahrer wird Ihrer Buchung zugeteilt und wartet am Strassenrand mit Namensschild.$vt$, $vt$Votre chauffeur est attribué à votre réservation et vous attend au trottoir avec une pancarte.$vt$, $vt$يُعيَّن سائقك لحجزك وينتظرك عند الرصيف مع لافتة باسمك.$vt$, false, false, null),
      ($vt$home.your-driver-is-booked$vt$, $vt$Your driver is booked$vt$, $vt$Ihr Fahrer ist gebucht$vt$, $vt$Votre chauffeur est réservé$vt$, $vt$تمّ حجز سائقك$vt$, false, false, null),
      ($vt$home.your-driver-is-booked-for-your-exact-pickup-time$vt$, $vt$Your driver is booked for your exact pickup time: pickup scheduled for 06:30, not the nearest available car.$vt$, $vt$Ihr Fahrer ist auf Ihre genaue Abholzeit gebucht: Abholung um 06:30, nicht das nächste freie Auto.$vt$, $vt$Votre chauffeur est réservé pour votre heure exacte : prise en charge à 06:30, pas la voiture la plus proche.$vt$, $vt$يُحجز سائقك لموعد استقبالك بالضبط: الاستقبال في 06:30، لا أقرب سيارة متاحة.$vt$, false, false, $vt$fixed example clock time, not a live count$vt$),
      ($vt$home.your-flight-lands$vt$, $vt$Your flight lands$vt$, $vt$Ihr Flug landet$vt$, $vt$Votre vol atterrit$vt$, $vt$هبوط رحلتك$vt$, false, false, null),
      ($vt$home.your-pickup-is-set-from-the-arrival-not-from-a-g$vt$, $vt$Your pickup is set from the arrival, not from a guess. If the flight moves, the pickup moves with it.$vt$, $vt$Die Abholung richtet sich nach der tatsächlichen Ankunft, nicht nach einer Schätzung. Verschiebt sich der Flug, verschiebt sich die Abholung mit.$vt$, $vt$La prise en charge suit l’arrivée réelle, pas une estimation. Si le vol bouge, la prise en charge bouge avec lui.$vt$, $vt$يُضبط موعد الاستقبال على وقت الوصول الفعلي لا على تخمين. وإذا تأخّرت الرحلة تأخّر الاستقبال معها.$vt$, false, false, null),
      ($vt$home.your-routes-fixed-price-appears-here-the-moment$vt$, $vt$Your route's fixed price appears here the moment you enter it. No meter, no surge, no charge until the last step.$vt$, $vt$Der Fixpreis Ihrer Route erscheint hier, sobald Sie sie eingeben. Kein Taxameter, keine Zuschläge, keine Belastung bis zum letzten Schritt.$vt$, $vt$Le prix fixe de votre trajet apparaît dès que vous le saisissez. Pas de compteur, pas de majoration, aucun débit avant la dernière étape.$vt$, $vt$يظهر السعر الثابت لمسارك فور إدخاله. بلا عدّاد ولا تسعير متغيّر ولا خصم قبل الخطوة الأخيرة.$vt$, false, false, null),
      ($vt$legal.100-refunded$vt$, $vt$100% refunded$vt$, $vt$100 % erstattet$vt$, $vt$Remboursé à 100 %$vt$, $vt$استرداد 100٪$vt$, false, false, $vt$fixed refund-policy percentage, not a live count$vt$),
      ($vt$legal.24-hours-before-pickup$vt$, $vt$24 hours before pickup$vt$, $vt$24 Stunden vor der Abholung$vt$, $vt$24 heures avant la prise en charge$vt$, $vt$24 ساعة قبل الانطلاق$vt$, false, false, $vt$fixed policy duration written into this specific copy, not a live count$vt$),
      ($vt$legal.24-hours-to-6-hours-before-pickup$vt$, $vt$24 hours to 6 hours before pickup$vt$, $vt$24 Stunden bis 6 Stunden vor der Abholung$vt$, $vt$24 heures à 6 heures avant la prise en charge$vt$, $vt$من 24 ساعة إلى 6 ساعات قبل الانطلاق$vt$, false, false, $vt$fixed policy duration written into this specific copy, not a live count$vt$),
      ($vt$legal.6-hours-through-pickup-and-after-pickup$vt$, $vt$6 hours through pickup, and after pickup if not completed$vt$, $vt$6 Stunden vor der Abholung bis danach, wenn die Fahrt nicht abgeschlossen ist$vt$, $vt$6 heures avant la prise en charge jusqu’après, si la course n’est pas terminée$vt$, $vt$من 6 ساعات قبل الانطلاق وبعده إن لم تكتمل الرحلة$vt$, false, false, $vt$fixed policy duration written into this specific copy, not a live count$vt$),
      ($vt$legal.72-hours$vt$, $vt$72 hours$vt$, $vt$72 Stunden$vt$, $vt$72 heures$vt$, $vt$72 ساعة$vt$, false, false, $vt$fixed policy duration written into this specific copy, not a live count$vt$),
      ($vt$legal.75-refunded$vt$, $vt$75% refunded$vt$, $vt$75 % erstattet$vt$, $vt$Remboursé à 75 %$vt$, $vt$استرداد 75٪$vt$, false, false, $vt$fixed refund-policy percentage, not a live count$vt$),
      ($vt$legal.a-booking-becomes-a-no-show-once-the-included-wa$vt$, $vt$A booking becomes a no-show once the included waiting time has run out and we have called your number$vt$, $vt$Eine Buchung wird zum Nichterscheinen, sobald die inbegriffene Wartezeit abgelaufen ist und wir Ihre Nummer$vt$, $vt$Une réservation devient une non-présentation dès que le temps d’attente inclus est écoulé et que nous avons appelé votre numéro$vt$, $vt$يصبح الحجز حالة عدم حضور بمجرد انتهاء وقت الانتظار المشمول واتصالنا برقمك$vt$, false, false, null),
      ($vt$legal.a-booking-counts-as-a-no-show-when-the-waiting-a$vt$, $vt$A booking counts as a no-show when the waiting allowance in section$vt$, $vt$Eine Buchung gilt als Nichterscheinen, wenn das Wartekontingent aus Abschnitt$vt$, $vt$Une réservation est considérée comme non-présentation lorsque le forfait d’attente de la section$vt$, $vt$يُعدّ الحجز حالة عدم حضور عندما تنتهي مدة الانتظار في القسم$vt$, false, false, null),
      ($vt$legal.a-change-requested-after-that-deadline-is-treate$vt$, $vt$A change requested after that deadline is treated as a cancellation and a new booking. It is worth calling us first: if a driver can still be moved, we will move them.$vt$, $vt$Eine nach dieser Frist gewünschte Änderung gilt als Stornierung und Neubuchung. Rufen Sie uns vorher an: Lässt sich ein Fahrer noch umdisponieren, tun wir es.$vt$, $vt$Une modification demandée après ce délai est traitée comme une annulation suivie d’une nouvelle réservation. Appelez-nous d’abord : si un chauffeur peut encore être déplacé, nous le déplacerons.$vt$, $vt$التعديل المطلوب بعد هذه المهلة يُعامَل كإلغاء وحجز جديد. يستحق الأمر اتصالًا بنا أولًا: إن أمكن نقل سائق، فسننقله.$vt$, false, false, null),
      ($vt$legal.a-driver-is-already-committed-to-your-journey-by$vt$, $vt$A driver is already committed to your journey by this point, which is what the retained share covers.$vt$, $vt$Zu diesem Zeitpunkt ist bereits ein Fahrer für Ihre Fahrt eingeplant — dafür steht der einbehaltene Anteil.$vt$, $vt$À ce stade, un chauffeur est déjà engagé sur votre trajet : c’est ce que couvre la part retenue.$vt$, $vt$عند هذه المرحلة يكون سائق قد التزم برحلتك، وهذا ما تغطّيه الحصة المحتجزة.$vt$, false, false, null),
      ($vt$legal.a-no-show-is-not-refunded-what-we-hold-on-record$vt$, $vt$A no-show is not refunded. What we hold on record as evidence is set out in the$vt$, $vt$Ein Nichterscheinen wird nicht rückerstattet. Was wir als Nachweis aufbewahren, steht in der$vt$, $vt$Une non-présentation n’est pas remboursée. Ce que nous conservons comme preuve est précisé dans la$vt$, $vt$لا يُسترد مبلغ عدم الحضور. وما نحتفظ به كدليل موضّح في$vt$, false, false, null),
      ($vt$legal.a-transfer-needs-your-name-two-addresses-a-time$vt$, $vt$A transfer needs your name, two addresses, a time and a way to reach you. This is what happens to that information, who else touches it, and how long it stays.$vt$, $vt$Ein Transfer braucht Ihren Namen, zwei Adressen, eine Zeit und einen Weg, Sie zu erreichen. Hier steht, was mit diesen Angaben geschieht, wer sie sonst noch berührt und wie lange sie bleiben.$vt$, $vt$Un transfert exige votre nom, deux adresses, une heure et un moyen de vous joindre. Voici ce qu’il advient de ces informations, qui d’autre y touche et combien de temps elles restent.$vt$, $vt$تحتاج الرحلة إلى اسمك وعنوانين ووقت ووسيلة للتواصل معك. وهنا ما يحدث لهذه المعلومات، ومَن يطّلع عليها غيرنا، وكم تبقى لدينا.$vt$, false, false, null),
      ($vt$legal.above-turning-a-category-off-stops-it-immediatel$vt$, $vt$above. Turning a category off stops it immediately; anything already collected is handled as set out in the$vt$, $vt$oben. Eine Kategorie abzuschalten stoppt sie sofort; bereits Erhobenes behandeln wir gemäss der$vt$, $vt$ci-dessus. Désactiver une catégorie l’arrête immédiatement ; ce qui a déjà été collecté est traité comme l’indique la$vt$, $vt$أعلاه. إيقاف فئة يوقفها فورًا؛ وما جُمع سابقًا يُعامَل وفق$vt$, false, false, null),
      ($vt$legal.accepted-methods$vt$, $vt$Accepted methods:$vt$, $vt$Akzeptierte Zahlungsmittel:$vt$, $vt$Moyens acceptés :$vt$, $vt$وسائل الدفع المقبولة:$vt$, false, false, null),
      ($vt$legal.account-and-marketing-preferences$vt$, $vt$Account and marketing preferences$vt$, $vt$Konto- und Marketingeinstellungen$vt$, $vt$Compte et préférences marketing$vt$, $vt$الحساب وتفضيلات التسويق$vt$, false, false, null),
      ($vt$legal.accounting-tax-and-the-trip-records-swiss-archiv$vt$, $vt$Accounting, tax, and the trip records Swiss archiving law requires us to hold — see section$vt$, $vt$Buchhaltung, Steuern und die Fahrtaufzeichnungen, die das Schweizer Archivierungsrecht von uns verlangt — siehe Abschnitt$vt$, $vt$Comptabilité, fiscalité et registres de courses que le droit suisse de l’archivage nous impose de conserver — voir la section$vt$, $vt$المحاسبة والضرائب وسجلات الرحلات التي يُلزمنا قانون الحفظ السويسري بالاحتفاظ بها — راجع القسم$vt$, false, false, null),
      ($vt$legal.additional-stops$vt$, $vt$Additional stops:$vt$, $vt$Weitere Stopps:$vt$, $vt$Arrêts supplémentaires :$vt$, $vt$محطات إضافية:$vt$, false, false, null),
      ($vt$legal.address-lookup-and-route-distance-united-states$vt$, $vt$Address lookup and route distance · United States$vt$, $vt$Adresssuche und Routendistanz · Vereinigte Staaten$vt$, $vt$Recherche d’adresse et distance d’itinéraire · États-Unis$vt$, $vt$البحث عن العناوين ومسافة المسار · الولايات المتحدة$vt$, false, false, null),
      ($vt$legal.after-pickup-time$vt$, $vt$After pickup time$vt$, $vt$Nach der Abholzeit$vt$, $vt$Après l’heure de prise en charge$vt$, $vt$بعد وقت الانطلاق$vt$, false, false, null),
      ($vt$legal.after-the-ride$vt$, $vt$After the ride$vt$, $vt$Nach der Fahrt$vt$, $vt$Après la course$vt$, $vt$بعد الرحلة$vt$, false, false, null),
      ($vt$legal.agreed-refund-paid-30-days-acceptance$vt$, $vt$Any refund we agree is paid within 30 days of your written acceptance of our decision.$vt$, $vt$Eine vereinbarte Rückerstattung zahlen wir innerhalb von 30 Tagen, nachdem Sie unseren Entscheid schriftlich angenommen haben.$vt$, $vt$Tout remboursement convenu est versé dans les 30 jours suivant votre acceptation écrite de notre décision.$vt$, $vt$أي مبلغ نتفق على ردّه يُدفع خلال 30 يومًا من موافقتك الكتابية على قرارنا.$vt$, false, false, $vt$fixed legal-page figure from the vamostaxi.eu terms or privacy text, owner-approved 2026-09-30 (docs/legal-source/vamostaxi-eu-2026-09-30/MAPPING.md list A), not a live count$vt$),
      ($vt$legal.airport-pickups$vt$, $vt$Airport pickups:$vt$, $vt$Abholung am Flughafen:$vt$, $vt$Prises en charge à l’aéroport :$vt$, $vt$الاستقبال في المطار:$vt$, false, false, null),
      ($vt$legal.airport-pickups-60-minutes-after-landing$vt$, $vt$Airport pickups: 60 minutes after landing, counted from the actual landing time we see against your flight number.$vt$, $vt$Abholung am Flughafen: 60 Minuten nach der Landung, gerechnet ab der tatsächlichen Landezeit, die wir zu Ihrer Flugnummer sehen.$vt$, $vt$Prises en charge à l’aéroport : 60 minutes après l’atterrissage, comptées à partir de l’heure d’atterrissage réelle relevée pour votre numéro de vol.$vt$, $vt$الاستقبال في المطار: 60 دقيقة بعد الهبوط، تُحتسب من وقت الهبوط الفعلي الذي نراه مقابل رقم رحلتك.$vt$, false, false, $vt$fixed legal-page figure from the vamostaxi.eu terms or privacy text, owner-approved 2026-09-30 (docs/legal-source/vamostaxi-eu-2026-09-30/MAPPING.md list A), not a live count$vt$),
      ($vt$legal.airport-pickups-60-minutes-landing$vt$, $vt$Airport pickups: 60 minutes from the actual landing time.$vt$, $vt$Abholung am Flughafen: 60 Minuten ab der tatsächlichen Landezeit.$vt$, $vt$Prises en charge à l’aéroport : 60 minutes à partir de l’heure d’atterrissage réelle.$vt$, $vt$الاستقبال في المطار: 60 دقيقة من وقت الهبوط الفعلي.$vt$, false, false, $vt$fixed legal-page figure from the vamostaxi.eu terms or privacy text, owner-approved 2026-09-30 (docs/legal-source/vamostaxi-eu-2026-09-30/MAPPING.md list A), not a live count$vt$),
      ($vt$legal.all-other-pickups$vt$, $vt$All other pickups:$vt$, $vt$Alle anderen Abholungen:$vt$, $vt$Toutes les autres prises en charge :$vt$, $vt$كل عمليات الاستقبال الأخرى:$vt$, false, false, null),
      ($vt$legal.all-other-pickups-30-minutes-booked$vt$, $vt$All other pickups: 30 minutes from the booked time.$vt$, $vt$Alle anderen Abholungen: 30 Minuten ab der gebuchten Zeit.$vt$, $vt$Toutes les autres prises en charge : 30 minutes à partir de l’heure réservée.$vt$, $vt$كل عمليات الاستقبال الأخرى: 30 دقيقة من الوقت المحجوز.$vt$, false, false, $vt$fixed legal-page figure from the vamostaxi.eu terms or privacy text, owner-approved 2026-09-30 (docs/legal-source/vamostaxi-eu-2026-09-30/MAPPING.md list A), not a live count$vt$),
      ($vt$legal.all-other-pickups-30-minutes-counted$vt$, $vt$All other pickups: 30 minutes, counted from the booked time.$vt$, $vt$Alle anderen Abholungen: 30 Minuten, gerechnet ab der gebuchten Zeit.$vt$, $vt$Toutes les autres prises en charge : 30 minutes, comptées à partir de l’heure réservée.$vt$, $vt$كل عمليات الاستقبال الأخرى: 30 دقيقة، تُحتسب من الوقت المحجوز.$vt$, false, false, $vt$fixed legal-page figure from the vamostaxi.eu terms or privacy text, owner-approved 2026-09-30 (docs/legal-source/vamostaxi-eu-2026-09-30/MAPPING.md list A), not a live count$vt$),
      ($vt$legal.always-to-the-original-payment-method-we-cannot$vt$, $vt$Always to the original payment method. We cannot redirect a refund to a different card or account.$vt$, $vt$Immer auf das ursprüngliche Zahlungsmittel. Wir können eine Rückerstattung nicht auf eine andere Karte oder ein anderes Konto umleiten.$vt$, $vt$Toujours sur le moyen de paiement d’origine. Nous ne pouvons pas rediriger un remboursement vers une autre carte ou un autre compte.$vt$, $vt$دائمًا إلى وسيلة الدفع الأصلية. لا يمكننا تحويل الاسترداد إلى بطاقة أو حساب آخر.$vt$, false, false, null),
      ($vt$legal.analytics-and-marketing-cookies-and-any-newslett$vt$, $vt$Analytics and marketing cookies, and any newsletter. You can withdraw it at any time without giving a reason.$vt$, $vt$Analyse- und Marketing-Cookies sowie ein allfälliger Newsletter. Sie können sie jederzeit ohne Begründung widerrufen.$vt$, $vt$Cookies d’analyse et de marketing, et toute newsletter. Vous pouvez le retirer à tout moment, sans motif.$vt$, $vt$ملفات التحليلات والتسويق وأي نشرة بريدية. يمكنك سحب موافقتك في أي وقت دون إبداء سبب.$vt$, false, false, null),
      ($vt$legal.analytics-off-until-you-allow-them$vt$, $vt$Analytics — off until you allow them$vt$, $vt$Analyse — aus, bis Sie sie erlauben$vt$, $vt$Analyse — désactivés jusqu’à votre autorisation$vt$, $vt$تحليلات — معطّلة حتى تسمح بها$vt$, false, false, null),
      ($vt$legal.and-one-piece-of-hand-luggage-a-vehicle-is-assig$vt$, $vt$and one piece of hand luggage. A vehicle is assigned on the count you gave us, so tell us if it changes.$vt$, $vt$und ein Handgepäckstück. Das Fahrzeug wird nach der von Ihnen genannten Zahl zugeteilt — sagen Sie uns Bescheid, wenn sie sich ändert.$vt$, $vt$et un bagage à main. Le véhicule est attribué selon le nombre que vous nous avez donné : dites-le-nous s’il change.$vt$, $vt$وقطعة أمتعة يدوية واحدة. تُخصَّص السيارة وفق العدد الذي ذكرته، فأخبرنا إن تغيّر.$vt$, false, false, null),
      ($vt$legal.and-quote-your-reference-we-will-do-it-for-you-a$vt$, $vt$and quote your reference. We will do it for you and send the confirmation.$vt$, $vt$an und nennen Sie Ihre Referenz. Wir erledigen es für Sie und senden die Bestätigung.$vt$, $vt$et indiquez votre référence. Nous le ferons pour vous et enverrons la confirmation.$vt$, $vt$واذكر رقمك المرجعي. سنقوم بذلك نيابةً عنك ونرسل التأكيد.$vt$, false, false, null),
