      ($vt$legal.no-show$vt$, $vt$No-show$vt$, $vt$Nichterscheinen$vt$, $vt$Non-présentation$vt$, $vt$عدم الحضور$vt$, false, false, null),
      ($vt$legal.no-show-or-not-cancelled$vt$, $vt$No-show, or not cancelled$vt$, $vt$Nichterscheinen oder nicht storniert$vt$, $vt$Non-présentation, ou non annulé$vt$, $vt$عدم حضور، أو لم يُلغَ$vt$, false, false, null),
      ($vt$legal.noshow-becomes-not-reached-30-60$vt$, $vt$A booking becomes a no-show when the included waiting time has run out and we have not reached you on the number or email on the booking within 30 minutes of the pickup time, or 60 minutes at an airport.$vt$, $vt$Eine Buchung wird zum Nichterscheinen, wenn die inbegriffene Wartezeit abgelaufen ist und wir Sie innerhalb von 30 Minuten nach der Abholzeit, am Flughafen innerhalb von 60 Minuten, weder unter der Nummer noch unter der E-Mail-Adresse der Buchung erreicht haben.$vt$, $vt$Une réservation devient une non-présentation lorsque le temps d’attente inclus est écoulé et que nous n’avons pas pu vous joindre au numéro ou à l’adresse e-mail de la réservation dans les 30 minutes suivant l’heure de prise en charge, ou dans les 60 minutes à l’aéroport.$vt$, $vt$يصبح الحجز حالة عدم حضور عندما ينتهي وقت الانتظار المشمول ولم نتمكن من الوصول إليك على الرقم أو البريد الإلكتروني المسجّلين في الحجز خلال 30 دقيقة من وقت الانطلاق، أو 60 دقيقة في المطار.$vt$, false, false, $vt$fixed legal-page figure from the vamostaxi.eu terms or privacy text, owner-approved 2026-09-30 (docs/legal-source/vamostaxi-eu-2026-09-30/MAPPING.md list A), not a live count$vt$),
      ($vt$legal.noshow-not-reached-30-60$vt$, $vt$has run out and we have not reached you on the number or email on the booking within 30 minutes of the pickup time, or 60 minutes at an airport.$vt$, $vt$abgelaufen ist und wir Sie innerhalb von 30 Minuten nach der Abholzeit, am Flughafen innerhalb von 60 Minuten, weder unter der Nummer noch unter der E-Mail-Adresse der Buchung erreicht haben.$vt$, $vt$est épuisé et que nous n’avons pas pu vous joindre au numéro ou à l’adresse e-mail de la réservation dans les 30 minutes suivant l’heure de prise en charge, ou dans les 60 minutes à l’aéroport.$vt$, $vt$ولم نتمكن من الوصول إليك على الرقم أو البريد الإلكتروني المسجّلين في الحجز خلال 30 دقيقة من وقت الانطلاق، أو 60 دقيقة في المطار.$vt$, false, false, $vt$fixed legal-page figure from the vamostaxi.eu terms or privacy text, owner-approved 2026-09-30 (docs/legal-source/vamostaxi-eu-2026-09-30/MAPPING.md list A), not a live count$vt$),
