      ($vt$legal.payment-and-tax-records$vt$, $vt$Payment and tax records$vt$, $vt$Zahlungs- und Steuerbelege$vt$, $vt$Registres de paiement et fiscaux$vt$, $vt$سجلات الدفع والضرائب$vt$, false, false, null),
      ($vt$legal.payment-metadata-only-the-amount-the-currency-th$vt$, $vt$Payment metadata only: the amount, the currency, the method, the last four digits, and whether it succeeded. Card numbers are entered on Stripe's own form and never reach our systems.$vt$, $vt$Nur Zahlungsmetadaten: Betrag, Währung, Zahlungsmittel, die letzten vier Ziffern und ob die Zahlung erfolgreich war. Kartennummern werden im Formular von Stripe eingegeben und erreichen unsere Systeme nie.$vt$, $vt$Uniquement les métadonnées de paiement : le montant, la devise, le moyen, les quatre derniers chiffres et le résultat. Les numéros de carte sont saisis sur le formulaire de Stripe et n’atteignent jamais nos systèmes.$vt$, $vt$بيانات الدفع الوصفية فقط: المبلغ والعملة والوسيلة وآخر أربعة أرقام ونتيجة العملية. تُدخَل أرقام البطاقات في نموذج Stripe ولا تصل أنظمتنا إطلاقًا.$vt$, false, false, null),
      ($vt$legal.payment-records$vt$, $vt$Payment records$vt$, $vt$Zahlungsbelege$vt$, $vt$Registres de paiement$vt$, $vt$سجلات الدفع$vt$, false, false, null),
      ($vt$legal.payment-records-statutory-periods$vt$, $vt$Kept for the statutory trade and tax retention periods.$vt$, $vt$Aufbewahrt während der gesetzlichen handels- und steuerrechtlichen Aufbewahrungsfristen.$vt$, $vt$Conservés pendant les délais légaux de conservation commerciaux et fiscaux.$vt$, $vt$تُحفظ طوال مدد الحفظ القانونية التجارية والضريبية.$vt$, false, false, null),
      ($vt$legal.per-stop$vt$, $vt$per stop.$vt$, $vt$pro Stopp.$vt$, $vt$par arrêt.$vt$, $vt$لكل محطة.$vt$, false, false, null),
      ($vt$legal.pickup-and-drop-off-address-and-any-additional-s$vt$, $vt$Pickup and drop-off address, and any additional stop.$vt$, $vt$Abhol- und Zieladresse sowie allfällige Zwischenstopps.$vt$, $vt$Adresse de prise en charge et de destination, ainsi que tout arrêt supplémentaire.$vt$, $vt$عنوان الانطلاق والوجهة وأي محطة إضافية.$vt$, false, false, null),
      ($vt$legal.pickup-and-drop-off-address-date-and-time-passen$vt$, $vt$Pickup and drop-off address, date and time, passenger and luggage count. This is enough to price a journey and nothing here identifies you.$vt$, $vt$Abhol- und Zieladresse, Datum und Uhrzeit, Zahl der Passagiere und Gepäckstücke. Das genügt, um eine Fahrt zu berechnen, und nichts davon identifiziert Sie.$vt$, $vt$Adresse de prise en charge et de destination, date et heure, nombre de passagers et de bagages. Cela suffit à tarifer un trajet et rien ici ne vous identifie.$vt$, $vt$عنوان الانطلاق والوجهة، والتاريخ والوقت، وعدد الركاب والحقائب. هذا يكفي لتسعير الرحلة ولا شيء منه يحدّد هويتك.$vt$, false, false, null),
      ($vt$legal.plans-change-this-page-says-exactly-what-happens$vt$, $vt$Plans change. This page says exactly what happens to your money when they do — and it is the one page that decides.$vt$, $vt$Pläne ändern sich. Diese Seite sagt genau, was dann mit Ihrem Geld geschieht — und sie ist die Seite, die entscheidet.$vt$, $vt$Les plans changent. Cette page dit exactement ce qu’il advient de votre argent dans ce cas — et c’est elle qui tranche.$vt$, $vt$الخطط تتغيّر. وهذه الصفحة تقول بالضبط ما يحدث لأموالك عندئذٍ — وهي الصفحة التي تحسم الأمر.$vt$, false, false, null),
      ($vt$legal.postal-address$vt$, $vt$Postal address$vt$, $vt$Postadresse$vt$, $vt$Adresse postale$vt$, $vt$العنوان البريدي$vt$, false, false, null),
