      ($vt$legal.related-documents$vt$, $vt$Related documents$vt$, $vt$Verwandte Dokumente$vt$, $vt$Documents liés$vt$, $vt$مستندات ذات صلة$vt$, false, false, null),
      ($vt$legal.remembers-whether-you-read-the-site-in-english-o$vt$, $vt$Remembers whether you read the site in English or German$vt$, $vt$Merkt sich, ob Sie die Website auf Englisch oder Deutsch lesen$vt$, $vt$Retient si vous lisez le site en anglais ou en allemand$vt$, $vt$يتذكّر ما إذا كنت تقرأ الموقع بالإنجليزية أم الألمانية$vt$, false, false, null),
      ($vt$legal.representative-in-the-eu$vt$, $vt$Representative in the EU$vt$, $vt$Vertretung in der EU$vt$, $vt$Représentant dans l’UE$vt$, $vt$الممثل في الاتحاد الأوروبي$vt$, false, false, null),
      ($vt$legal.request-answer-within-30-days$vt$, $vt$with the booking reference if there is one. We answer within 30 days; in complex cases we may take up to 60 days more.$vt$, $vt$mit der Buchungsreferenz, falls vorhanden. Wir antworten innerhalb von 30 Tagen; in komplexen Fällen können wir bis zu 60 Tage länger brauchen.$vt$, $vt$avec la référence de réservation, s’il y en a une. Nous répondons sous 30 jours ; dans les cas complexes, ce délai peut être prolongé de 60 jours au plus.$vt$, $vt$مع رقم الحجز إن وُجد. ونردّ خلال 30 يومًا، وقد نحتاج في الحالات المعقّدة إلى 60 يومًا إضافية كحدّ أقصى.$vt$, false, false, $vt$fixed legal-page figure from the vamostaxi.eu terms or privacy text, owner-approved 2026-09-30 (docs/legal-source/vamostaxi-eu-2026-09-30/MAPPING.md list A), not a live count$vt$),
      ($vt$legal.reset-my-choice$vt$, $vt$Reset my choice$vt$, $vt$Meine Wahl zurücksetzen$vt$, $vt$Réinitialiser mon choix$vt$, $vt$أعد ضبط اختياري$vt$, false, false, null),
      ($vt$legal.resetting-clears-the-record-and-brings-the-banne$vt$, $vt$Resetting clears the record and brings the banner back, which is also how you check what a first-time visitor sees.$vt$, $vt$Das Zurücksetzen löscht den Nachweis und holt das Banner zurück — so prüfen Sie auch, was eine Erstbesucherin sieht.$vt$, $vt$La réinitialisation efface l’enregistrement et fait revenir la bannière, ce qui permet aussi de voir ce qu’aperçoit un nouveau visiteur.$vt$, $vt$إعادة الضبط تمسح السجل وتعيد الشريط، وهي أيضًا طريقتك لمعرفة ما يراه زائر لأول مرة.$vt$, false, false, null),
      ($vt$legal.responsible-for-content$vt$, $vt$Responsible for content$vt$, $vt$Inhaltlich verantwortlich$vt$, $vt$Responsable du contenu$vt$, $vt$المسؤول عن المحتوى$vt$, false, false, null),
      ($vt$legal.restrict-or-object-to-a-particular-use$vt$, $vt$Restrict or object to a particular use$vt$, $vt$Eine bestimmte Bearbeitung einschränken oder ihr widersprechen$vt$, $vt$Limiter un usage précis ou s’y opposer$vt$, $vt$تقييد استخدام معيّن أو الاعتراض عليه$vt$, false, false, null),
      ($vt$legal.revfadp-gdpr$vt$, $vt$revFADP · GDPR$vt$, $vt$revDSG · DSGVO$vt$, $vt$nLPD · RGPD$vt$, $vt$قانون حماية البيانات السويسري المنقّح · اللائحة الأوروبية$vt$, false, false, null),
