      ($vt$ops.staffRoster.col-role$vt$, $vt$Role$vt$, $vt$Rolle$vt$, $vt$Rôle$vt$, $vt$الدور$vt$, false, false, null),
      ($vt$ops.staffRoster.confirm$vt$, $vt$Confirm$vt$, $vt$Bestaetigen$vt$, $vt$Confirmer$vt$, $vt$تأكيد$vt$, false, false, null),
      ($vt$ops.staffRoster.deactivate$vt$, $vt$Deactivate$vt$, $vt$Deaktivieren$vt$, $vt$Désactiver$vt$, $vt$تعطيل$vt$, false, false, null),
      ($vt$ops.staffRoster.deactivate-body$vt$, $vt$The next minted token will not carry a staff claim. An already-issued access token stays valid for up to {minutes} minutes (the configured jwt_expiry). This console does not revoke existing sessions.$vt$, $vt$Das naechste Token traegt keinen Staff-Claim mehr. Ein bereits ausgestelltes Access-Token bleibt bis zu {minutes} Minuten gueltig (konfiguriertes jwt_expiry). Diese Konsole widerruft bestehende Sitzungen nicht.$vt$, $vt$Le prochain jeton n’emportera plus de claim staff. Un jeton d’accès déjà émis reste valable jusqu’à {minutes} minutes (jwt_expiry configuré). Cette console ne révoque pas les sessions existantes.$vt$, $vt$الرمز التالي لن يحمل مطالبة طاقم. رمز الوصول الصادر سابقاً يبقى صالحاً حتى {minutes} دقيقة (jwt_expiry المضبوط). هذه الواجهة لا تلغي الجلسات القائمة.$vt$, false, false, null),
      ($vt$ops.staffRoster.deactivate-title$vt$, $vt$Deactivate this account?$vt$, $vt$Dieses Konto deaktivieren?$vt$, $vt$Désactiver ce compte ?$vt$, $vt$تعطيل هذا الحساب؟$vt$, false, false, null),
      ($vt$ops.staffRoster.demote$vt$, $vt$Make dispatcher$vt$, $vt$Zum Dispatcher machen$vt$, $vt$Passer dispatcher$vt$, $vt$جعله موزّعاً$vt$, false, false, null),
      ($vt$ops.staffRoster.demote-title$vt$, $vt$Make this person a dispatcher?$vt$, $vt$Diese Person zum Dispatcher machen?$vt$, $vt$Passer cette personne dispatcher ?$vt$, $vt$جعل هذا الشخص موزّعاً؟$vt$, false, false, null),
      ($vt$ops.staffRoster.email$vt$, $vt$Email$vt$, $vt$E-Mail$vt$, $vt$E-mail$vt$, $vt$البريد$vt$, false, false, null),
      ($vt$ops.staffRoster.empty$vt$, $vt$No staff rows.$vt$, $vt$Keine Personalzeilen.$vt$, $vt$Aucune ligne de personnel.$vt$, $vt$لا صفوف طاقم.$vt$, false, false, null),
      ($vt$ops.staffRoster.enrol-note$vt$, $vt$mfa_enrolled is a display flag. The aal2 check is the actual gate — an account that has not enrolled cannot reach ops data. A staff member who loses their authenticator contacts the owner; admin reset of MFA is a launch-window item and is not offered here.$vt$, $vt$mfa_enrolled ist ein Anzeige-Flag. Die aal2-Pruefung ist die eigentliche Grenze — ohne Enrolment gibt es keine Ops-Daten. Wer den Authenticator verliert, kontaktiert den Owner; ein Admin-Reset ist ein Launch-Window-Punkt und fehlt hier absichtlich.$vt$, $vt$mfa_enrolled est un drapeau d’affichage. Le contrôle aal2 est la vraie porte — un compte non inscrit n’atteint pas les données ops. Qui perd l’authentificateur contacte le propriétaire ; une réinitialisation admin est un point de la fenêtre de lancement et n’est pas proposée ici.$vt$, $vt$mfa_enrolled علامة عرض. فحص aal2 هو البوابة الفعلية — حساب بلا تسجيل لا يصل إلى بيانات التشغيل. من يفقد المصادق يتواصل مع المالك؛ إعادة تعيين المسؤول بند نافذة الإطلاق وليست معروضة هنا.$vt$, false, false, $vt$aal2 is the authenticator-assurance level name, not a live count$vt$),
      ($vt$ops.staffRoster.enrolled$vt$, $vt$Enrolled$vt$, $vt$Eingetragen$vt$, $vt$Inscrit$vt$, $vt$مسجّل$vt$, false, false, null),
      ($vt$ops.staffRoster.error$vt$, $vt$That change did not save.$vt$, $vt$Die Aenderung wurde nicht gespeichert.$vt$, $vt$Cette modification n’a pas été enregistrée.$vt$, $vt$لم يُحفظ ذلك التغيير.$vt$, false, false, null),
      ($vt$ops.staffRoster.error-already$vt$, $vt$That address already has a staff invite.$vt$, $vt$Diese Adresse hat bereits eine Einladung.$vt$, $vt$Cette adresse a déjà une invitation.$vt$, $vt$هذا العنوان لديه دعوة طاقم مسبقاً.$vt$, false, false, null),
      ($vt$ops.staffRoster.error-delivery$vt$, $vt$Invite delivery is not configured yet.$vt$, $vt$Der Versand der Einladung ist noch nicht eingerichtet.$vt$, $vt$L’envoi des invitations n’est pas encore configuré.$vt$, $vt$إرسال الدعوات غير مضبوط بعد.$vt$, false, false, null),
      ($vt$ops.staffRoster.error-invalid$vt$, $vt$Check the email address and role.$vt$, $vt$E-Mail und Rolle pruefen.$vt$, $vt$Vérifier l’e-mail et le rôle.$vt$, $vt$تحقق من البريد والدور.$vt$, false, false, null),
      ($vt$ops.staffRoster.error-role$vt$, $vt$Role must be dispatcher or admin.$vt$, $vt$Rolle muss Dispatcher oder Admin sein.$vt$, $vt$Le rôle doit être dispatcher ou admin.$vt$, $vt$الدور يجب أن يكون موزّعاً أو مسؤولاً.$vt$, false, false, null),
      ($vt$ops.staffRoster.error-row$vt$, $vt$The staff row could not be written. The invite was rolled back.$vt$, $vt$Die Personalzeile konnte nicht geschrieben werden. Die Einladung wurde zurueckgenommen.$vt$, $vt$La ligne de personnel n’a pas pu être écrite. L’invitation a été annulée.$vt$, $vt$تعذّر كتابة صف الطاقم. أُلغيت الدعوة.$vt$, false, false, null),
      ($vt$ops.staffRoster.inactive$vt$, $vt$Inactive$vt$, $vt$Inaktiv$vt$, $vt$Inactif$vt$, $vt$غير نشط$vt$, false, false, null),
      ($vt$ops.staffRoster.invite$vt$, $vt$Invite$vt$, $vt$Einladen$vt$, $vt$Inviter$vt$, $vt$دعوة$vt$, false, false, null),
      ($vt$ops.staffRoster.invite-copy-gap$vt$, $vt$The invitation email still uses placeholder wording until the owner copy lands.$vt$, $vt$Die Einladungsmail nutzt noch Platzhaltertext, bis der Owner-Text vorliegt.$vt$, $vt$L’e-mail d’invitation utilise encore un texte provisoire, jusqu’à ce que le texte du propriétaire arrive.$vt$, $vt$رسالة الدعوة ما زالت تستخدم نصاً مؤقتاً إلى أن يصل نص المالك.$vt$, false, false, null),
      ($vt$ops.staffRoster.invite-title$vt$, $vt$Invite a staff member$vt$, $vt$Ein Mitglied einladen$vt$, $vt$Inviter un membre$vt$, $vt$دعوة عضو في الطاقم$vt$, false, false, null),
      ($vt$ops.staffRoster.last-admin$vt$, $vt$The last active admin cannot be removed.$vt$, $vt$Der letzte aktive Admin kann nicht entfernt werden.$vt$, $vt$Le dernier admin actif ne peut pas être retiré.$vt$, $vt$لا يمكن إزالة آخر مسؤول نشط.$vt$, false, false, null),
