      ($vt$ops.staffRoster.reactivate$vt$, $vt$Reactivate$vt$, $vt$Reaktivieren$vt$, $vt$Réactiver$vt$, $vt$إعادة تفعيل$vt$, false, false, null),
      ($vt$ops.staffRoster.reactivate-body$vt$, $vt$The next minted token will carry a staff claim again.$vt$, $vt$Das naechste Token traegt wieder einen Staff-Claim.$vt$, $vt$Le prochain jeton emportera de nouveau un claim staff.$vt$, $vt$الرمز التالي سيحمل مطالبة طاقم مجدداً.$vt$, false, false, null),
      ($vt$ops.staffRoster.reactivate-title$vt$, $vt$Reactivate this account?$vt$, $vt$Dieses Konto reaktivieren?$vt$, $vt$Réactiver ce compte ?$vt$, $vt$إعادة تفعيل هذا الحساب؟$vt$, false, false, null),
      ($vt$ops.staffRoster.refused$vt$, $vt$This roster is admin-only. A dispatcher session cannot read staff rows — that is the permission boundary, not an empty list.$vt$, $vt$Diese Liste ist nur fuer Admins. Eine Dispatcher-Sitzung liest keine Personalzeilen — das ist die Rechtegrenze, keine leere Liste.$vt$, $vt$Cette liste est réservée aux admins. Une session dispatcher ne lit aucune ligne de personnel — c’est la frontière de droits, pas une liste vide.$vt$, $vt$هذه القائمة للمسؤولين فقط. جلسة الموزّع لا تقرأ صفوف الطاقم — هذا حدّ الصلاحية، وليست قائمة فارغة.$vt$, false, false, null),
      ($vt$ops.staffRoster.role$vt$, $vt$Role$vt$, $vt$Rolle$vt$, $vt$Rôle$vt$, $vt$الدور$vt$, false, false, null),
      ($vt$ops.staffRoster.role-admin$vt$, $vt$Admin$vt$, $vt$Admin$vt$, $vt$Admin$vt$, $vt$مسؤول$vt$, false, false, null),
      ($vt$ops.staffRoster.role-confirm-body$vt$, $vt$The new role is written now. It takes effect on their next token refresh — an already-issued access token keeps the previous role until then.$vt$, $vt$Die neue Rolle wird jetzt geschrieben. Sie gilt ab dem naechsten Token-Refresh — ein bereits ausgestelltes Access-Token behaelt die alte Rolle bis dahin.$vt$, $vt$Le nouveau rôle est écrit maintenant. Il s’applique au prochain rafraîchissement du jeton — un jeton d’accès déjà émis garde l’ancien rôle jusque-là.$vt$, $vt$الدور الجديد يُكتب الآن. يسري عند تجديد الرمز التالي — رمز الوصول الصادر سابقاً يحتفظ بالدور السابق حتى ذلك الحين.$vt$, false, false, null),
